// Development-only fresh native Tentacle MClientCaps, MClientCapRelease,
// MClientLease, MClientSnap and MClientQuota encoder and decoder.
// Pinned v20.2.4 commit 7f793731f1b39eb4f465e960113d2363c311b964.
// Ceph headers/library LGPL-2.1. Only public/native objects and encoders are
// invoked; no upstream implementation or socket/Go-generated bytes copied.
// Envelope projection and receipt helpers are adapted from the repository MDS
// request wrapper; this wrapper also writes the middle (xattr) segment.
//
// Messages are constructed the way the native senders fill them:
// Locker::issue_caps with CInode::encode_cap_message (GRANT),
// Migrator::finish_export_inode_caps (EXPORT), MDCache::do_cap_import
// (IMPORT), Locker::handle_client_caps (FLUSH_ACK), Client::send_cap (UPDATE),
// MetaSession::enqueue_cap_release, Locker::revoke_client_leases and
// Client::handle_lease (lease REVOKE/RELEASE),
// MDCache::do_realm_invalidate_and_update_notify (snaprealm SPLIT) and
// MDCache::broadcast_quota_to_client. Field values are explicit test inputs.
// Snap traces use the native SnapRealmInfoNew encoder, xattr blobs the native
// map<string,bufferptr> encoder and the flock blob the native ceph_filelock
// encoder in the Client::_encode_filelocks layout. The receipts report what
// separate default-constructed native objects decoded, not the wrapper's
// input constants.
#include "messages/MClientCaps.h"
#include "messages/MClientCapRelease.h"
#include "messages/MClientLease.h"
#include "messages/MClientSnap.h"
#include "messages/MClientQuota.h"
#include "common/snap_types.h"
#include "msg/async/frames_v2.h"
#include "include/ceph_features.h"
#include <cstdio>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <initializer_list>
#include <iostream>
#include <map>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>
namespace {
// MClientCaps::encode_payload drops to header version 1 without FLOCK and to
// version 2 without EXPORT_PEER, and omits inline data without
// MDS_INLINE_DATA. The other four messages ignore features.
constexpr uint64_t features = CEPH_FEATURE_FLOCK | CEPH_FEATURE_EXPORT_PEER |
                              CEPH_FEATURE_MDS_INLINE_DATA;
constexpr ceph_tid_t flush_tid = 77;
constexpr epoch_t epoch_barrier = 21;

void write_segment(const std::filesystem::path& path,
                   const ceph::buffer::list& segment) {
  const auto bytes = segment.to_str();
  std::ofstream out(path, std::ios::binary);
  out.exceptions(std::ios::failbit | std::ios::badbit);
  out.write(bytes.data(), bytes.size());
}

std::string hex(const std::string& bytes) {
  constexpr char digits[] = "0123456789abcdef";
  std::string out;
  for (unsigned char b : bytes) {
    out += digits[b >> 4];
    out += digits[b & 15];
  }
  return out;
}

std::string hex(const std::vector<uint8_t>& bytes) {
  return hex(std::string(bytes.begin(), bytes.end()));
}

std::string json_string(const std::string& value) {
  std::string out = "\"";
  for (unsigned char c : value) {
    if (c == '"' || c == '\\') {
      out += '\\';
      out += char(c);
    } else if (c < 0x20 || c >= 0x7f) {
      char escaped[8];
      std::snprintf(escaped, sizeof(escaped), "\\u%04x", unsigned(c));
      out += escaped;
    } else {
      out += char(c);
    }
  }
  return out + "\"";
}

// Minimal JSON builders for the decoder receipts.
std::string jnum(uint64_t v) { return std::to_string(v); }
std::string jsnum(int64_t v) { return std::to_string(v); }
std::string jhex(const std::string& bytes) { return json_string(hex(bytes)); }
std::string jkv(const std::string& key, const std::string& value) {
  return json_string(key) + ":" + value;
}
std::string jobj(std::initializer_list<std::string> fields) {
  std::string out = "{";
  bool first = true;
  for (const auto& f : fields) {
    out += (first ? "" : ",") + f;
    first = false;
  }
  return out + "}";
}
std::string jarr(const std::vector<std::string>& items) {
  std::string out = "[";
  for (size_t i = 0; i < items.size(); ++i)
    out += (i ? "," : "") + items[i];
  return out + "]";
}
std::string time_json(const utime_t& t) {
  return jobj({jkv("sec", jnum(t.sec())), jkv("nsec", jnum(t.nsec()))});
}

void emit(const std::filesystem::path& root, const std::string& name,
          Message& message, int expected_type, uint16_t expected_version,
          ceph_tid_t expected_tid) {
  if (message.get_payload().length() != 0 ||
      message.get_middle().length() != 0 || message.get_data().length() != 0)
    throw std::runtime_error("fresh encoder input must have empty front, middle and data");
  message.set_seq(1);  // Explicit offline transport input, not live session state.
  message.set_priority(CEPH_MSG_PRIO_DEFAULT);
  // Invoke the canonical Message::encode path exactly once on a fresh object.
  // Its empty-payload branch dispatches the unchanged virtual encode_payload
  // (which also fills the MClientCaps middle) and normalizes a zero compat
  // version to the header version. No decoded message or cached payload is
  // reused.
  message.encode(features, MSG_CRC_ALL, true);
  if (message.get_type() != expected_type ||
      message.get_header().version != expected_version ||
      message.get_header().compat_version != 1 ||
      message.get_header().tid != expected_tid)
    throw std::runtime_error("native canonical encoder did not select the expected envelope for " + name);
  const auto& header = message.get_header();
  const auto& footer = message.get_footer();
  if (header.front_len != message.get_payload().length() ||
      header.middle_len != message.get_middle().length() ||
      header.data_len != message.get_data().length())
    throw std::runtime_error("native envelope lengths disagree with payloads");
  // Project the fresh native envelope into the native v2 struct, as required
  // by its public MessageFrame API. This does not execute ProtocolV2's live
  // write_message/session path. ACK sequence 3 is another explicit test input.
  ceph_msg_header2 header2{};
  header2.seq = header.seq;
  header2.tid = header.tid;
  header2.type = header.type;
  header2.priority = header.priority;
  header2.version = header.version;
  header2.data_off = header.data_off;
  header2.ack_seq = 3;
  header2.flags = footer.flags;
  header2.compat_version = header.compat_version;
  header2.reserved = header.reserved;
  auto frame = ceph::msgr::v2::MessageFrame::Encode(
      header2, message.get_payload(), message.get_middle(), message.get_data());
  ceph::buffer::list encoded_header;
  encoded_header.append(reinterpret_cast<const char*>(&frame.header()),
                        sizeof(frame.header()));
  if (encoded_header.length() != 41)
    throw std::runtime_error("native v2 message header size changed");
  write_segment(root / (name + ".header.bin"), encoded_header);
  std::ofstream metadata(root / (name + ".native-header.json"));
  metadata.exceptions(std::ios::failbit | std::ios::badbit);
  metadata << "{\"type\":" << uint16_t(header.type)
           << ",\"version\":" << uint16_t(header.version)
           << ",\"compat\":" << uint16_t(header.compat_version)
           << ",\"tid\":" << uint64_t(header.tid)
           << ",\"seq\":" << uint64_t(header.seq)
           << ",\"priority\":" << uint16_t(header.priority)
           << ",\"front_len\":" << uint32_t(header.front_len)
           << ",\"middle_len\":" << uint32_t(header.middle_len)
           << ",\"data_len\":" << uint32_t(header.data_len)
           << ",\"data_off\":" << uint16_t(header.data_off)
           << ",\"flags\":" << unsigned(footer.flags)
           << ",\"ack_seq\":" << uint64_t(frame.header().ack_seq)
           << ",\"reserved\":" << uint16_t(header.reserved) << "}\n";
  write_segment(root / (name + ".front.bin"), message.get_payload());
  write_segment(root / (name + ".middle.bin"), message.get_middle());
  write_segment(root / (name + ".data.bin"), message.get_data());
  std::cout << name << "\t" << message.get_payload().length() << "\t"
            << message.get_middle().length() << "\t"
            << message.get_data().length() << "\n";
}

void write_receipt(const std::filesystem::path& root, const std::string& name,
                   const std::string& receipt) {
  std::ofstream out(root / (name + ".decoded.json"));
  out.exceptions(std::ios::failbit | std::ios::badbit);
  out << receipt << "\n";
}

// Decode the fresh source's segments with a separate default-constructed
// native object, as the receiving Messenger hands them to decode_payload.
template <class M>
ceph::ref_t<M> decode_fresh(const ceph::ref_t<M>& source) {
  auto decoded = ceph::make_message<M>();
  decoded->set_header(source->get_header());
  ceph::buffer::list payload(source->get_payload());
  decoded->set_payload(payload);
  ceph::buffer::list middle(source->get_middle());
  decoded->set_middle(middle);
  decoded->decode_payload();
  return decoded;
}

std::string envelope_json(const Message& m) {
  return jkv("message_type", jnum(m.get_header().type)) + "," +
         jkv("version", jnum(m.get_header().version)) + "," +
         jkv("tid", jnum(m.get_tid()));
}

std::string with_envelope(const Message& m, const std::string& object) {
  // object is a non-empty jobj(); splice the envelope keys in front.
  return "{" + envelope_json(m) + "," + object.substr(1);
}

std::string realm_json(const SnapRealmInfoNew& r) {
  std::vector<std::string> snaps, prior;
  for (auto snap : r.info.my_snaps)
    snaps.push_back(jnum(snap));
  for (auto snap : r.info.prior_parent_snaps)
    prior.push_back(jnum(snap));
  return jobj({jkv("ino", jnum(r.info.h.ino)), jkv("created", jnum(r.info.h.created)),
                 jkv("parent", jnum(r.info.h.parent)), jkv("parent_since", jnum(r.info.h.parent_since)),
                 jkv("seq", jnum(r.info.h.seq)), jkv("num_snaps", jnum(r.info.h.num_snaps)),
                 jkv("num_prior_parent_snaps", jnum(r.info.h.num_prior_parent_snaps)),
                 jkv("my_snaps", jarr(snaps)), jkv("prior_parent_snaps", jarr(prior)),
                 jkv("last_modified", time_json(r.last_modified)),
                 jkv("change_attr", jnum(r.change_attr))});
}

// Client::update_snap_trace with CEPHFS_FEATURE_NEW_SNAPREALM_INFO.
std::string realms_json(const ceph::buffer::list& bl) {
  using ceph::decode;
  std::vector<std::string> realms;
  auto p = bl.cbegin();
  while (!p.end()) {
    SnapRealmInfoNew info;
    decode(info, p);
    realms.push_back(realm_json(info));
  }
  return jarr(realms);
}

// Client::add_update_inode / handle_cap_grant decode the xattr blob as
// map<string, bufferptr>.
std::string xattrs_json(const ceph::buffer::list& bl) {
  using ceph::decode;
  std::vector<std::string> xattrs;
  if (bl.length()) {
    std::map<std::string, ceph::bufferptr> decoded;
    auto q = bl.cbegin();
    decode(decoded, q);
    if (!q.end())
      throw std::runtime_error("native xattr map left trailing bytes");
    for (const auto& [key, value] : decoded)
      xattrs.push_back(jobj({jkv("name", json_string(key)),
                               jkv("value_hex", jhex(std::string(value.c_str(), value.length())))}));
  }
  return jarr(xattrs);
}

// ------------------------------------------------------------------- caps

void emit_caps(const std::filesystem::path& root, const std::string& name,
               const ceph::ref_t<MClientCaps>& source, ceph_tid_t tid) {
  emit(root, name, *source, CEPH_MSG_CLIENT_CAPS, 12, tid);
  auto d = decode_fresh(source);
  const auto& h = d->head;
  const bool exported = h.op == CEPH_CAP_OP_EXPORT;
  const bool imported = h.op == CEPH_CAP_OP_IMPORT;
  if (std::memcmp(&h, &source->head, sizeof(h)) != 0 ||
      d->get_middle().length() != h.xattr_len ||
      !d->snapbl.contents_equal(source->snapbl) ||
      !d->xattrbl.contents_equal(source->xattrbl) ||
      !d->flockbl.contents_equal(source->flockbl) ||
      d->inline_version != source->inline_version ||
      !d->inline_data.contents_equal(source->inline_data) ||
      d->osd_epoch_barrier != source->osd_epoch_barrier ||
      d->oldest_flush_tid != source->oldest_flush_tid ||
      d->caller_uid != source->caller_uid || d->caller_gid != source->caller_gid ||
      d->get_layout().pool_ns != source->get_layout().pool_ns ||
      d->btime != source->btime || d->change_attr != source->change_attr ||
      d->flags != source->flags || d->nfiles != source->nfiles ||
      d->nsubdirs != source->nsubdirs || d->fscrypt_auth != source->fscrypt_auth ||
      d->fscrypt_file != source->fscrypt_file)
    throw std::runtime_error("native caps decode for " + name);
  if (!exported &&
      (d->size != source->size || d->max_size != source->max_size ||
       d->truncate_size != source->truncate_size ||
       d->truncate_seq != source->truncate_seq || d->mtime != source->mtime ||
       d->atime != source->atime || d->ctime != source->ctime ||
       d->time_warp_seq != source->time_warp_seq ||
       d->get_layout().stripe_unit != source->get_layout().stripe_unit ||
       d->get_layout().stripe_count != source->get_layout().stripe_count ||
       d->get_layout().object_size != source->get_layout().object_size ||
       d->get_layout().pool_id != source->get_layout().pool_id))
    throw std::runtime_error("native caps body decode for " + name);
  if ((exported || imported) &&
      std::memcmp(&d->peer, &source->peer, sizeof(d->peer)) != 0)
    throw std::runtime_error("native caps peer decode for " + name);
  // The default-constructed decoder only assigns the peer for EXPORT and
  // IMPORT; for any other op it is not a decoded field.
  std::string peer = "null";
  if (exported || imported)
    peer = jobj({jkv("cap_id", jnum(d->peer.cap_id)), jkv("issue_seq", jnum(d->peer.issue_seq)),
                 jkv("mseq", jnum(d->peer.mseq)), jkv("mds", jsnum(int32_t(uint32_t(d->peer.mds)))),
                 jkv("flags", jnum(d->peer.flags))});
  const auto& l = d->get_layout();
  write_receipt(root, name, with_envelope(*d, jobj({
      jkv("op", jnum(h.op)),
      jkv("ino", jnum(h.ino)),
      jkv("realm", jnum(h.realm)),
      jkv("cap_id", jnum(h.cap_id)),
      jkv("seq", jnum(h.seq)),
      jkv("issue_seq", jnum(h.issue_seq)),
      jkv("caps", jnum(h.caps)),
      jkv("wanted", jnum(h.wanted)),
      jkv("dirty", jnum(h.dirty)),
      jkv("migrate_seq", jnum(h.migrate_seq)),
      jkv("snap_follows", jnum(h.snap_follows)),
      jkv("snap_trace_len", jnum(h.snap_trace_len)),
      jkv("uid", jnum(h.uid)),
      jkv("gid", jnum(h.gid)),
      jkv("mode", jnum(h.mode)),
      jkv("nlink", jnum(h.nlink)),
      jkv("xattr_len", jnum(h.xattr_len)),
      jkv("xattr_version", jnum(h.xattr_version)),
      jkv("size", jnum(d->size)),
      jkv("max_size", jnum(d->max_size)),
      jkv("truncate_size", jnum(d->truncate_size)),
      jkv("truncate_seq", jnum(d->truncate_seq)),
      jkv("mtime", time_json(d->mtime)),
      jkv("atime", time_json(d->atime)),
      jkv("ctime", time_json(d->ctime)),
      // file_layout_t after from_legacy (a zeroed legacy layout becomes
      // pool -1); pool_ns is the separately decoded v8 field.
      jkv("layout", jobj({jkv("stripe_unit", jnum(l.stripe_unit)),
                              jkv("stripe_count", jnum(l.stripe_count)),
                              jkv("object_size", jnum(l.object_size)),
                              jkv("pool_id", jsnum(l.pool_id)),
                              jkv("pool_ns", json_string(l.pool_ns))})),
      jkv("time_warp_seq", jnum(d->time_warp_seq)),
      jkv("peer", peer),
      jkv("snapbl_hex", jhex(d->snapbl.to_str())),
      jkv("snap_realms", realms_json(d->snapbl)),
      jkv("xattrbl_hex", jhex(d->xattrbl.to_str())),
      jkv("xattrs", xattrs_json(d->xattrbl)),
      jkv("flockbl_hex", jhex(d->flockbl.to_str())),
      jkv("inline_version", jnum(d->inline_version)),
      jkv("inline_data_hex", jhex(d->inline_data.to_str())),
      jkv("osd_epoch_barrier", jnum(d->osd_epoch_barrier)),
      jkv("oldest_flush_tid", jnum(d->oldest_flush_tid)),
      jkv("caller_uid", jnum(d->caller_uid)),
      jkv("caller_gid", jnum(d->caller_gid)),
      jkv("btime", time_json(d->btime)),
      jkv("change_attr", jnum(d->change_attr)),
      jkv("flags", jnum(d->flags)),
      jkv("nfiles", jsnum(d->nfiles)),
      jkv("nsubdirs", jsnum(d->nsubdirs)),
      jkv("fscrypt_auth_hex", json_string(hex(d->fscrypt_auth))),
      jkv("fscrypt_file_hex", json_string(hex(d->fscrypt_file)))})));
}

// ------------------------------------------------------- release/lease/snap

void emit_cap_release(const std::filesystem::path& root, const std::string& name,
                      const ceph::ref_t<MClientCapRelease>& source) {
  emit(root, name, *source, CEPH_MSG_CLIENT_CAPRELEASE, 2, 0);
  auto d = decode_fresh(source);
  if (d->head.num != source->caps.size() || d->caps.size() != source->caps.size() ||
      std::memcmp(d->caps.data(), source->caps.data(), d->caps.size() * sizeof(ceph_mds_cap_item)) != 0 ||
      d->osd_epoch_barrier != source->osd_epoch_barrier)
    throw std::runtime_error("native cap release decode for " + name);
  std::vector<std::string> items;
  for (const auto& item : d->caps)
    items.push_back(jobj({jkv("ino", jnum(item.ino)), jkv("cap_id", jnum(item.cap_id)),
                          jkv("migrate_seq", jnum(item.migrate_seq)),
                          jkv("issue_seq", jnum(item.issue_seq))}));
  write_receipt(root, name, with_envelope(*d, jobj({
      jkv("num", jnum(d->head.num)),
      jkv("caps", jarr(items)),
      jkv("osd_epoch_barrier", jnum(d->osd_epoch_barrier))})));
}

void emit_lease(const std::filesystem::path& root, const std::string& name,
                const ceph::ref_t<MClientLease>& source) {
  emit(root, name, *source, CEPH_MSG_CLIENT_LEASE, 1, 0);
  auto d = decode_fresh(source);
  if (std::memcmp(&d->h, &source->h, sizeof(d->h)) != 0 || d->dname != source->dname)
    throw std::runtime_error("native lease decode for " + name);
  write_receipt(root, name, with_envelope(*d, jobj({
      jkv("action", jnum(d->h.action)),
      jkv("mask", jnum(d->h.mask)),
      jkv("ino", jnum(d->h.ino)),
      jkv("first", jnum(d->h.first)),
      jkv("last", jnum(d->h.last)),
      jkv("seq", jnum(d->h.seq)),
      jkv("duration_ms", jnum(d->h.duration_ms)),
      jkv("dname", json_string(d->dname))})));
}

void emit_snap(const std::filesystem::path& root, const std::string& name,
               const ceph::ref_t<MClientSnap>& source) {
  emit(root, name, *source, CEPH_MSG_CLIENT_SNAP, 1, 0);
  auto d = decode_fresh(source);
  if (std::memcmp(&d->head, &source->head, sizeof(d->head)) != 0 ||
      d->split_inos != source->split_inos || d->split_realms != source->split_realms ||
      !d->bl.contents_equal(source->bl))
    throw std::runtime_error("native snap decode for " + name);
  std::vector<std::string> inos, realms;
  for (auto ino : d->split_inos)
    inos.push_back(jnum(ino));
  for (auto ino : d->split_realms)
    realms.push_back(jnum(ino));
  write_receipt(root, name, with_envelope(*d, jobj({
      jkv("op", jnum(d->head.op)),
      jkv("split", jnum(d->head.split)),
      jkv("num_split_inos", jnum(d->head.num_split_inos)),
      jkv("num_split_realms", jnum(d->head.num_split_realms)),
      jkv("trace_len", jnum(d->head.trace_len)),
      jkv("split_inos", jarr(inos)),
      jkv("split_realms", jarr(realms)),
      jkv("trace_hex", jhex(d->bl.to_str())),
      jkv("snap_realms", realms_json(d->bl))})));
}

void emit_quota(const std::filesystem::path& root, const std::string& name,
                const ceph::ref_t<MClientQuota>& source) {
  emit(root, name, *source, CEPH_MSG_CLIENT_QUOTA, 1, 0);
  auto d = decode_fresh(source);
  if (d->ino != source->ino || d->rstat.rctime != source->rstat.rctime ||
      d->rstat.rbytes != source->rstat.rbytes || d->rstat.rfiles != source->rstat.rfiles ||
      d->rstat.rsubdirs != source->rstat.rsubdirs || !(d->quota == source->quota))
    throw std::runtime_error("native quota decode for " + name);
  write_receipt(root, name, with_envelope(*d, jobj({
      jkv("ino", jnum(d->ino)),
      jkv("rctime", time_json(d->rstat.rctime)),
      jkv("rbytes", jsnum(d->rstat.rbytes)),
      jkv("rfiles", jsnum(d->rstat.rfiles)),
      jkv("rsubdirs", jsnum(d->rstat.rsubdirs)),
      jkv("max_bytes", jsnum(d->quota.max_bytes)),
      jkv("max_files", jsnum(d->quota.max_files))})));
}

// ---------------------------------------------------------------- inputs

SnapRealmInfoNew realm(uint64_t ino, uint64_t created, uint64_t parent, uint64_t parent_since,
                       uint64_t seq, std::vector<snapid_t> snaps, std::vector<snapid_t> prior,
                       utime_t last_modified, uint64_t change_attr) {
  SnapRealmInfo info(inodeno_t(ino), created, seq, parent_since);
  info.h.parent = parent;
  info.my_snaps = std::move(snaps);
  info.prior_parent_snaps = std::move(prior);
  return SnapRealmInfoNew(info, last_modified, change_attr);
}

ceph::buffer::list xattr_blob(const std::vector<std::pair<std::string, std::string>>& entries) {
  using ceph::encode;
  std::map<std::string, ceph::bufferptr> xattrs;
  for (const auto& [key, value] : entries)
    xattrs[key] = ceph::bufferptr(value.data(), value.size());
  ceph::buffer::list bl;
  encode(xattrs, bl);
  return bl;
}

// Client::_encode_filelocks layout: fcntl lock count and locks, then flock
// lock count and locks.
ceph::buffer::list flock_blob() {
  using ceph::encode;
  ceph_filelock lock{};
  lock.start = 4096;
  lock.length = 8192;
  lock.client = 4100;
  lock.owner = 0x9999;
  lock.pid = 321;
  lock.type = CEPH_LOCK_EXCL;
  ceph::buffer::list bl;
  encode(uint32_t(1), bl);
  encode(lock, bl);
  encode(uint32_t(0), bl);
  return bl;
}

const inodeno_t file_ino(0x10000000001);
const inodeno_t dir_ino(0x10000000000);
constexpr int file_caps = CEPH_CAP_PIN | CEPH_CAP_AUTH_SHARED | CEPH_CAP_LINK_SHARED |
                          CEPH_CAP_XATTR_SHARED | CEPH_CAP_FILE_SHARED | CEPH_CAP_FILE_CACHE |
                          CEPH_CAP_FILE_RD | CEPH_CAP_FILE_WR | CEPH_CAP_FILE_BUFFER;
}  // namespace

int main(int argc, char** argv) {
  try {
    if (argc != 2)
      throw std::runtime_error("usage: native-mds-caps-encoder OUTPUT_DIR");
    const std::filesystem::path root(argv[1]);
    std::filesystem::create_directories(root);
    using ceph::encode;

    // GRANT for a regular file with every head and body field distinctive,
    // a one-realm snap trace, xattrs in the middle segment, a flock blob,
    // inline data and every v4..v12 extension.
    auto grant = ceph::make_message<MClientCaps>(
        CEPH_CAP_OP_GRANT, file_ino, dir_ino, uint64_t(0x7777), ceph_seq_t(11),
        file_caps, CEPH_CAP_FILE_RD | CEPH_CAP_FILE_WR | CEPH_CAP_FILE_CACHE,
        CEPH_CAP_AUTH_EXCL, ceph_seq_t(12), ceph_seq_t(13), epoch_barrier);
    grant->set_snap_follows(14);
    grant->head.uid = 1000;
    grant->head.gid = 1001;
    grant->head.mode = 0100644;
    grant->head.nlink = 2;
    grant->head.xattr_version = 7;
    grant->size = 12345;
    grant->max_size = 4194304;
    grant->truncate_size = 100;
    grant->truncate_seq = 5;
    grant->mtime = utime_t(1700000101, 2);
    grant->atime = utime_t(1700000102, 3);
    grant->ctime = utime_t(1700000100, 1);
    {
      file_layout_t layout(4194304, 2, 8388608);
      layout.pool_id = 3;
      layout.pool_ns = "ns-a";
      grant->set_layout(layout);
    }
    grant->time_warp_seq = 4;
    encode(realm(dir_ino, 2, CEPH_INO_ROOT, 3, 5, {5, 4}, {2}, utime_t(1700000200, 7), 8),
           grant->snapbl);
    grant->xattrbl = xattr_blob({{"user.a", "va"}, {"user.bin", std::string("\x00\xff\x10", 3)}});
    grant->flockbl = flock_blob();
    grant->inline_version = 6;
    grant->inline_data.append("inline!");
    grant->oldest_flush_tid = 9;
    grant->caller_uid = 2000;
    grant->caller_gid = 2001;
    grant->btime = utime_t(1700000000, 9);
    grant->change_attr = 0x99;
    grant->flags = MClientCaps::FLAG_SYNC;
    grant->nfiles = 6;
    grant->nsubdirs = 7;
    grant->fscrypt_auth = {0xaa, 0xbb};
    grant->fscrypt_file = {0xcc};
    emit_caps(root, "mds-caps-native-caps-grant", grant, 0);

    // EXPORT as Migrator::finish_export_inode_caps sends it: the six-argument
    // constructor and the destination peer; the body is the peer zero-padded to the
    // non-export body size, and nfiles/nsubdirs keep their -1 defaults.
    auto exported = ceph::make_message<MClientCaps>(
        CEPH_CAP_OP_EXPORT, file_ino, inodeno_t(0), uint64_t(0x7777), ceph_seq_t(12), epoch_barrier);
    exported->set_cap_peer(0x8888, 15, 16, 1, CEPH_CAP_FLAG_AUTH);
    emit_caps(root, "mds-caps-native-caps-export", exported, 0);

    // IMPORT as MDCache::do_cap_import sends it for a directory: an unset
    // directory layout (legacy pool 0, decoded as pool -1), a two-realm snap
    // trace, no inline data (CEPH_INLINE_NONE) and the source peer appended
    // after the flock blob.
    auto imported = ceph::make_message<MClientCaps>(
        CEPH_CAP_OP_IMPORT, dir_ino, dir_ino, uint64_t(0x8888), ceph_seq_t(3),
        CEPH_CAP_PIN | CEPH_CAP_AUTH_SHARED | CEPH_CAP_FILE_SHARED, CEPH_CAP_FILE_SHARED,
        0, ceph_seq_t(16), ceph_seq_t(2), epoch_barrier);
    imported->head.uid = 1000;
    imported->head.gid = 1001;
    imported->head.mode = 040755;
    imported->head.nlink = 1;
    imported->mtime = utime_t(1700000300, 0);
    imported->atime = utime_t(1700000300, 0);
    imported->ctime = utime_t(1700000301, 500);
    imported->btime = utime_t(1700000000, 0);
    imported->change_attr = 4;
    imported->nfiles = 3;
    imported->nsubdirs = 1;
    imported->inline_version = CEPH_INLINE_NONE;
    encode(realm(dir_ino, 2, CEPH_INO_ROOT, 3, 5, {5, 4}, {2}, utime_t(1700000200, 7), 8),
           imported->snapbl);
    encode(realm(CEPH_INO_ROOT, 1, 0, 1, 3, {3}, {}, utime_t(1700000201, 0), 2),
           imported->snapbl);
    imported->set_cap_peer(0x7777, 13, 12, 0, CEPH_CAP_FLAG_AUTH);
    emit_caps(root, "mds-caps-native-caps-import", imported, 0);

    // FLUSH_ACK as Locker::handle_client_caps acknowledges client flush TID
    // 77; the MDS fills no body, so the default layout and dirstat remain.
    auto ack = ceph::make_message<MClientCaps>(
        CEPH_CAP_OP_FLUSH_ACK, file_ino, inodeno_t(0), uint64_t(0x7777), ceph_seq_t(11),
        file_caps, 0, CEPH_CAP_FILE_WR | CEPH_CAP_XATTR_EXCL, ceph_seq_t(0), ceph_seq_t(0), epoch_barrier);
    ack->set_snap_follows(5);
    ack->set_client_tid(flush_tid);
    ack->set_oldest_flush_tid(76);
    emit_caps(root, "mds-caps-native-caps-flush-ack", ack, flush_tid);

    // UPDATE as Client::send_cap sends a dirty flush with TID 77: realm 0,
    // caller -1/-1, an xattr flush in the middle segment, the inode's
    // CEPH_INLINE_NONE inline version for a FILE_WR flush, no layout and
    // default dirstat counts.
    auto update = ceph::make_message<MClientCaps>(
        CEPH_CAP_OP_UPDATE, file_ino, inodeno_t(0), uint64_t(0x7777), ceph_seq_t(11),
        file_caps, CEPH_CAP_FILE_RD | CEPH_CAP_FILE_WR, CEPH_CAP_FILE_WR | CEPH_CAP_XATTR_EXCL,
        ceph_seq_t(12), ceph_seq_t(13), epoch_barrier);
    update->caller_uid = -1;
    update->caller_gid = -1;
    update->set_tid(flush_tid);
    update->head.uid = 1000;
    update->head.gid = 1001;
    update->head.mode = 0100600;
    update->head.nlink = 1;
    update->xattrbl = xattr_blob({{"user.flushed", "yes"}});
    update->head.xattr_version = 8;
    update->size = 20000;
    update->set_max_size(8388608);
    update->truncate_seq = 5;
    update->truncate_size = 100;
    update->mtime = utime_t(1700000500, 123);
    update->atime = utime_t(1700000400, 456);
    update->ctime = utime_t(1700000500, 124);
    update->btime = utime_t(1700000000, 9);
    update->time_warp_seq = 4;
    update->change_attr = 0x9a;
    update->flags = MClientCaps::FLAG_PENDING_CAPSNAP;
    update->inline_version = CEPH_INLINE_NONE;
    update->set_snap_follows(5);
    update->set_oldest_flush_tid(76);
    emit_caps(root, "mds-caps-native-caps-update", update, flush_tid);

    // Two cap releases with the client's OSD epoch barrier.
    auto release = ceph::make_message<MClientCapRelease>();
    {
      ceph_mds_cap_item item{};
      item.ino = 0x10000000003;
      item.cap_id = 0x31;
      item.migrate_seq = 2;
      item.issue_seq = 7;
      release->caps.push_back(item);
      item.ino = 0x10000000004;
      item.cap_id = 0x32;
      item.migrate_seq = 0;
      item.issue_seq = 1;
      release->caps.push_back(item);
    }
    release->osd_epoch_barrier = epoch_barrier;
    emit_cap_release(root, "mds-caps-native-cap-release", release);

    // Locker::revoke_client_leases: dentry lease revoke on the parent
    // directory, open-ended at CEPH_NOSNAP.
    auto revoke = ceph::make_message<MClientLease>(
        CEPH_MDS_LEASE_REVOKE, ceph_seq_t(4), CEPH_LEASE_VALID, uint64_t(dir_ino), uint64_t(2),
        uint64_t(CEPH_NOSNAP), std::string_view("file"));
    emit_lease(root, "mds-caps-native-lease-revoke", revoke);

    // Client::handle_lease answering that revoke.
    auto lease_release = ceph::make_message<MClientLease>(
        CEPH_MDS_LEASE_RELEASE, ceph_seq_t(4), CEPH_LEASE_VALID, uint64_t(dir_ino), uint64_t(2),
        uint64_t(CEPH_NOSNAP), std::string_view("file"));
    emit_lease(root, "mds-caps-native-lease-release", lease_release);

    // MDCache::do_realm_invalidate_and_update_notify snaprealm split: a new
    // realm at 0x10000000005 takes two inodes and one child realm; the trace
    // carries the new realm and its parent.
    auto split = ceph::make_message<MClientSnap>(CEPH_SNAP_OP_SPLIT);
    split->head.split = 0x10000000005;
    split->split_inos = {inodeno_t(0x10000000006), inodeno_t(0x10000000007)};
    split->split_realms = {inodeno_t(0x10000000008)};
    encode(realm(0x10000000005, 9, dir_ino, 9, 9, {9}, {5, 4}, utime_t(1700000600, 1), 3),
           split->bl);
    encode(realm(dir_ino, 2, CEPH_INO_ROOT, 3, 9, {9, 5, 4}, {2}, utime_t(1700000600, 1), 9),
           split->bl);
    emit_snap(root, "mds-caps-native-snap-split", split);

    // MDCache::broadcast_quota_to_client.
    auto quota = ceph::make_message<MClientQuota>();
    quota->ino = dir_ino;
    quota->rstat.rctime = utime_t(1700000400, 5);
    quota->rstat.rbytes = 1 << 20;
    quota->rstat.rfiles = 12;
    quota->rstat.rsubdirs = 3;
    quota->quota.max_bytes = int64_t(1) << 30;
    quota->quota.max_files = 1000;
    emit_quota(root, "mds-caps-native-quota", quota);
    return 0;
  } catch (const std::exception& error) {
    std::cerr << error.what() << "\n";
    return 1;
  }
}
